const payload = $json.body ?? $json;
const forbiddenTerms = ['patient', 'client name', 'symptom', 'diagnosis', 'insurance', 'member id', 'appointment reason', 'clinical note', 'psychotherapy note'];
const haystack = JSON.stringify(payload).toLowerCase();
const flaggedTerms = forbiddenTerms.filter((term) => haystack.includes(term));
const accepted = flaggedTerms.length === 0 && payload.phiAcknowledgement === true;
return [{
  json: {
    accepted,
    leadId: accepted ? `DEMO-THER-${Date.now()}` : null,
    flaggedTerms,
    message: accepted ? 'Accepted demo non-PHI practice audit lead.' : 'Rejected for demo review. Remove patient-specific details before submitting.',
    lead: accepted ? {
      practiceName: payload.practiceName,
      contactName: payload.contactName,
      workEmail: payload.workEmail,
      workPhone: payload.workPhone,
      website: payload.website,
      providerCount: payload.providerCount,
      ehrTools: payload.ehrTools,
      adminPain: payload.adminPain,
      monthlyVolume: payload.monthlyVolume,
      source: payload.source ?? 'therapist-practice-audit'
    } : payload
  }
}];
